CommonFunctions = {};
function CommonFunctions.CheckDirtyWords(word)
    local dirtyWords = DataManager.GetData("DirtyWordsData");
    local tmpWord = word;
    for i, v in pairs(dirtyWords) do
        local starIndex, endIndex = string.find(word, tostring(v.Words));
        if(starIndex ~= nil and endIndex ~= nil) then
            local wordLength = string.len(v.Words);
            local tmpStr = "";
            for i = 1, wordLength do
                tmpStr = tmpStr .. "*";
            end
            word = string.gsub(word,v.Words,tmpStr);
        end
    end
    return word;
end

function CommonFunctions.Sensitivewords(word)
    local starIndex, endIndex = string.find(word, "*");
    if(starIndex ~= nil and endIndex ~= nil) then
        return true;
    end
    return false;
end

function CommonFunctions.CheckContainNum(word)
    local word = string.gsub(word,"%d*", "")
    return word;
end

